const VERSION="v6",PRECACHE="precache-v6",RUNTIME="runtime-v6",PRECACHE_URLS=["./","./index.html","./assets/styles/main.css","./assets/js/boot.min.js","./assets/fonts/schibsted-grotesk.woff2","./assets/fonts/jetbrains-mono.woff2","./assets/brand/mark-duo.svg","./manifest.json"];self.addEventListener("install",s=>{s.waitUntil(caches.open(PRECACHE).then(t=>t.addAll(PRECACHE_URLS)).then(()=>self.skipWaiting()))}),self.addEventListener("activate",s=>{const t=[PRECACHE,RUNTIME];s.waitUntil(caches.keys().then(c=>{const e=c.filter(n=>!t.includes(n));return Promise.all(e.map(n=>caches.delete(n))).then(()=>e.length)}).then(c=>self.clients.claim().then(()=>{if(c)return self.clients.matchAll({type:"window"}).then(e=>Promise.all(e.map(n=>n.navigate(n.url).catch(()=>{}))))})))}),self.addEventListener("fetch",s=>{const t=s.request;if(t.method!=="GET")return;const c=new URL(t.url);if(c.origin===self.location.origin&&!c.pathname.includes("/assets/js/world/")){if(t.mode==="navigate"){s.respondWith(fetch(t).then(e=>{if(e.ok){const n=e.clone();caches.open(RUNTIME).then(a=>a.put(t,n))}return e}).catch(()=>caches.match(t).then(e=>e||caches.match("./index.html"))));return}s.respondWith(caches.match(t).then(e=>{const n=fetch(t).then(a=>{if(a.ok){const i=a.clone();caches.open(RUNTIME).then(r=>r.put(t,i))}return a}).catch(()=>e);return e||n}))}});
